; Node: Start - "gf_start_1776512093056"
gameflow_node_gf_start_1776512093056:
    db NODE_TYPE_START
    dw gameflow_node_gf_start_1776512093056_data
    dw gameflow_node_gf_start_1776512093056_conn

gameflow_node_gf_start_1776512093056_data:
    dw gameflow_node_gf_start_1776512093056_init    ; Initialization routine address
    db 2    ; Initialization routine bank

gameflow_node_gf_start_1776512093056_conn:
    db CONNECTION_DEFAULT
    dw gameflow_node_gfn_1776512097888
    db CONNECTION_END

; ------------------------------------------------------------------
; gameflow_node_gf_start_1776512093056_init
; Initialization routine for Start node
; Initializes global variables and MSX systems
; ------------------------------------------------------------------
gameflow_node_gf_start_1776512093056_init:
    ; === Core Game Systems Initialization (ALWAYS required) ===
    call init_game_systems

    ; === Global Variables Initialization ===
    ld a, 0
    ld (global_var_buttons_activated), a    ; buttons_activated = 0
    ld a, 0
    ld (global_var_buttons_reward_granted), a    ; buttons_reward_granted = 0

    ret

; Node: WorldLink - "gfn_1776512097888"
gameflow_node_gfn_1776512097888:
    db NODE_TYPE_WORLD_LINK
    dw gameflow_node_gfn_1776512097888_data
    dw gameflow_node_gfn_1776512097888_conn

gameflow_node_gfn_1776512097888_data:
    dw load_world_worldmap_1776512078647_far
    db ((load_world_worldmap_1776512078647_far - #4000) / #2000)
    dw gameflow_node_gfn_1776512097888_init
    db 2

gameflow_node_gfn_1776512097888_conn:
    db CONNECTION_DEFAULT
    dw gameflow_node_gfn_1776512119008
    db CONNECTION_END

; ------------------------------------------------------------------
; gameflow_node_gfn_1776512097888_init
; Initialization routine for WorldLink node
; Applies optional per-world global values when entering the world
; ------------------------------------------------------------------
gameflow_node_gfn_1776512097888_init:
    ret

; Node: End - "gfn_1776512119008"
gameflow_node_gfn_1776512119008:
    db NODE_TYPE_END
    dw gameflow_no_data
    dw gameflow_node_gfn_1776512119008_conn

gameflow_node_gfn_1776512119008_conn:
    db CONNECTION_DEFAULT
    dw 0
    db CONNECTION_END


