    ld a, 0
    ld (global_var_score+1), a    ; Score high byte = 0
    ld a, 0
    ld (global_var_time_remaining), a    ; TimeRemaining low byte = 0
    ld a, 0
    ld (global_var_time_remaining+1), a    ; TimeRemaining high byte = 0
