boss_1_mono1_phase_0:
    db #00, #00, #08, #0E    ; healthThreshold,buildType,width,height
    dw ((boss_1_mono1_phase_0_tiles & #1FFF) | #A000), #FFFF, #FFFF, #FFFF, ((boss_1_mono1_phase_0_attacks & #1FFF) | #A000), ((boss_1_mono1_phase_0_behavior & #1FFF) | #A000), #FFFF, ((boss_1_mono1_phase_0_weak & #1FFF) | #A000)    ; tileMatrix,collision,neck,crush,attacks,behavior,forms,weak
