; @mideas:block id=runtime.screens.load_screen_new_dialog_screen_777377884059.loader kind=routine owner=screens roots=load_screen_new_dialog_screen_777377884059
load_screen_new_dialog_screen_777377884059:
    ; Load New Dialog Screen screen (fast direct port access)
    ld a, 1
    ld (current_screen_engine), a
    ld a, #FF
    ld (autocontrol_screen_id), a
    ; Set VDP colors FIRST (before loading screen data)
    ld a, 1           ; Background color
    ld b, 1       ; Border color
    call call_set_screen_colors_resident
    ; Initialize character 0 (empty cells) with background color
    ld a, 1           ; Background color for char 0
    call call_init_char0_color_resident
    ld a, (current_screen2_tilebank_id)
    cp SCREEN2_TILEBANK_TILEBANK_1776511918552_ID
    jr z, .load_new_dialog_screen_777377884059_tilebank_ready
    call load_tilebank_tilebank_1776511918552_patterns_to_vram_far
    call load_tilebank_tilebank_1776511918552_colors_to_vram_far
    ld a, SCREEN2_TILEBANK_TILEBANK_1776511918552_ID
    ld (current_screen2_tilebank_id), a
    xor a
    ld (vram_cache_font_ready), a
    call call_init_font_system_resident
.load_new_dialog_screen_777377884059_tilebank_ready:
    ; Clear hardware sprites on screen switch to avoid visual carry-over
    call call_clear_all_sprites_resident
    call call_update_sprites_to_vram_resident
    ; Rebuild mutable runtime screen background from RAM cache
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_LAYOUT
    call resource_load_screen_layout_cached
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_EFFECTS_LAYOUT
    call resource_load_effects_layout_cached
    ld a, RESOURCE_ID_BEHAVIOR_NEW_DIALOG_SCREEN_1_DATA
    call resource_load_behavior_map_cached
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_INTERACTION_TYPE_MAP
    ld de, runtime_interaction_type_map
    call resource_load_to_ram_by_id
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_INTERACTION_VALUE_MAP
    ld de, runtime_interaction_value_map
    call resource_load_to_ram_by_id
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_INTERACTION_TARGET_MAP
    ld de, runtime_interaction_target_map
    call resource_load_to_ram_by_id
    ld a, 0
    ld (current_effect_zone_count), a
    or a
    jr z, .load_new_dialog_screen_777377884059_zones_done
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_EFFECT_ZONE_TABLE
    call resource_load_effect_zone_table_cached
.load_new_dialog_screen_777377884059_zones_done:
    ; Transition->WorldLink reveal mode prepares runtime_screen_layout first,
    ; then GameFlow reveals it by raster after the world loader returns.
    ld a, (gameflow_reveal_world_after_load)
    or a
    jr nz, load_screen_new_dialog_screen_777377884059_skip_vram_copy
    ; Now load screen layout (full 32x24) from runtime RAM buffer
    ld hl, runtime_screen_layout
    ld de, NAMETBL
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    call FAST_LDIRVM           ; Fast VRAM write (direct port access)
load_screen_new_dialog_screen_777377884059_skip_vram_copy:
    ld a, 0
    ld (current_screen_anim_group_count), a
    ld a, 1
    ld (current_screen_entity_count), a
    ld a, 13
    ld (current_screen_sprite_pattern_slots), a
    ld a, SCREEN_NEW_DIALOG_SCREEN_1_SUMMARY_FLAGS
    ld (current_screen_summary_flags), a
    ld a, SCREEN_NEW_DIALOG_SCREEN_1_BOSS_COUNT
    ld (current_screen_boss_count), a
    or a
    jp z, load_new_dialog_screen_777377884059_boss_done
    ld a, RESOURCE_ID_SCREEN_NEW_DIALOG_SCREEN_1_BOSS_TABLE
    ld de, current_screen_boss_entry
    call resource_load_to_ram_by_id
    jr nc, .load_new_dialog_screen_777377884059_boss_done_loaded
    xor a
    ld (current_screen_boss_count), a
    jp load_new_dialog_screen_777377884059_boss_done
.load_new_dialog_screen_777377884059_boss_done_loaded:
    ld hl, current_screen_boss_entry
    ld (current_screen_boss_table), hl
    ld a, #FF
    ld (current_screen_boss_table_bank), a
load_new_dialog_screen_777377884059_boss_done:


    ; Initialize collision system pointers for this screen
    ld hl, runtime_screen_layout
    ld (current_screen_layout), hl
    ld a, #FF
    ld (current_screen_layout_bank), a
    ld hl, runtime_behavior_map
    ld (current_behavior_map), hl
    ld a, #FF
    ld (current_behavior_map_bank), a
    ld a, l
    ld (behavior_cache_map_l), a
    ld a, h
    ld (behavior_cache_map_h), a
    ld a, #FF
    ld (behavior_cache_row), a
    xor a
    ld (secret_zone_active), a
    ld (secret_zone_rect_x), a
    ld (secret_zone_rect_y), a
    ld (secret_zone_rect_w), a
    ld (secret_zone_rect_h), a
    ld hl, entity_button_contact_active
    ld de, entity_button_contact_active + 1
    ld bc, 31
    ld (hl), a
    ldir
    ret
; @mideas:endblock id=runtime.screens.load_screen_new_dialog_screen_777377884059.loader


