load_font_colors:
    ld de, CLRTBL2                ; Bank 0 Base
    call load_font_colors_to_bank
    ret

load_font_colors_all_banks:
    ld de, CLRTBL2                ; Bank 0 Base
    call load_font_colors_to_bank

    ld de, CLRTBL2 + #800         ; Bank 1 Base
    call load_font_colors_to_bank

    ld de, CLRTBL2 + #1000        ; Bank 2 Base
    call load_font_colors_to_bank
    ret

; Helper: Load font colors to a specific bank
; Input: DE = Bank Base Address
load_font_colors_to_bank:
    ld ix, FONT_CHAR_INDEX        ; Pointer to ASCII codes
    ld iy, FONT_COLOR_DATA        ; Pointer to color data
    ld b, FONT_CHAR_COUNT         ; Number of characters to load


.load_colors_loop:
    push bc                       ; Save loop counter
    push de                       ; Save bank base address

    ; Get ASCII code
    ld a, (ix)                    ; A = ASCII code
    inc ix                        ; Next index

    ; Calculate VRAM offset: Base + (ASCII * 8)
    ld l, a
    ld h, 0
    add hl, hl                    ; * 2
    add hl, hl                    ; * 4
    add hl, hl                    ; * 8
    add hl, de                    ; Add Base Address
    ex de, hl                     ; DE = VRAM Destination

    ; Prepare source pointer
    push iy
    pop hl                        ; HL = Source Color (IY)

    ; Copy 8 bytes
    ld bc, 8
    call FAST_LDIRVM              ; Copy from HL(RAM) to DE(VRAM)

    ; Advance source pointer
    ld bc, 8
    add iy, bc                    ; IY += 8

    pop de                        ; Restore bank base
    pop bc                        ; Restore loop counter
    djnz .load_colors_loop
    ret
; @mideas:endblock id=runtime.font.loading

; ==================================================================
; TEXT RENDERING FUNCTIONS (Based on Mideas renderMSX1TextToDataURL)
; ==================================================================

; Print string to Screen 2 name table (text mode compatible)
; HL = string pointer (null-terminated), DE = VRAM position
print_string_screen2:
    push bc
    ld b, 0                        ; Character counter

print_string_loop:
    ld a, (hl)                     ; Get character
    or a                           ; Check for null terminator
    jr z, print_string_end         ; End if null

    ; Write character to VRAM Name Table
    ; FAST_WRTVRM signature: A = data, HL = VRAM address
    ; A already has character, HL already has VRAM address
    push hl                        ; Save string pointer
    push de                        ; Save VRAM position
    ex de, hl                      ; Swap: DE = string ptr, HL = VRAM address for FAST_WRTVRM
    call FAST_WRTVRM               ; Write character to VRAM (fast)
    pop de                         ; Restore VRAM position
    pop hl                         ; Restore string pointer

    ; Move to next character
    inc hl                         ; Next character in string
    inc de                         ; Next position in VRAM
    inc b                          ; Count characters
    ld a, b
    cp 32                          ; Limit to screen width
    jr nz, print_string_loop       ; Continue if not at edge

print_string_end:
    pop bc
    ret

; Initialize font system for Screen 2 text rendering
init_font_system:
    ld a, (vram_cache_font_ready)
    or a
    ret nz
    ; Load custom font patterns and colors
    call load_all_font_banks       ; Load patterns to all banks
    call load_font_colors_all_banks ; Load colors to all banks
    ld a, 1
    ld (vram_cache_font_ready), a
    ret

reload_font_system:
    xor a
    ld (vram_cache_font_ready), a
    jp init_font_system

; ==================================================================
; END OF FONT DATA
; ==================================================================


; --- End of Far Bank 13 — pad to 8KB boundary ---
BANK_13_USED_END:
    ds #8000 - $, #FF
    org FAR_BANK_13_ROM_START + #2000

; ##################################################################
; FAR BANK 14 — [#6000h-#8000h] FAR CODE: animtiles
; Accessed ONLY via trampolines in bank 0 (entrypoint_far labels).
; At runtime: bank0 saves P1, maps bank14 to P1,
; calls routine, then restores P1.
; NOTE: routines in this bank MUST only call code in bank 0 or
;       primary banks (1-2). No far-to-far calls allowed.
; ##################################################################
FAR_BANK_14_ROM_START:

    org #6000

; @mideas:block id=runtime.animtiles.core kind=routine owner=animtiles roots=init_animated_tiles,update_animated_tiles,update_animated_tiles_vram,anim_upload_char_frame,set_animation_speed,register_animated_tile,get_tile_animation_frame
; ==================================================================
; ANIMATED TILES SYSTEM
; File: animtiles.asm
; Description: Background tile animation for water, lava, fire, etc.
; ==================================================================

; Auto-detected animated groups:
;   frame groups: 3
;   transform groups: 0

; ==================================================================
; ANIMATED TILES CONSTANTS
; ==================================================================

; Animation speeds (in frames)
ANIM_SPEED_SLOW         EQU 15      ; ~250ms (water)
ANIM_SPEED_MEDIUM       EQU 8       ; ~133ms (lava)
ANIM_SPEED_FAST         EQU 4       ; ~66ms (fire)

; Maximum animated tiles
MAX_ANIM_TILES          EQU 3
ANIM_TILE_ENTRY_SIZE    EQU 7       ; char, chars, frames, speed, bytesPerFrame, ptr(2)
ANIM_TRANS_ENTRY_SIZE   EQU 4       ; char, chars, opCode, flags
ANIM_TILE_DATA_BANK     EQU 0       ; Deprecated: anim data is local to animtiles code bank

; ==================================================================
; ANIMATED TILES INITIALIZATION
; ==================================================================

init_animated_tiles:
    ; Initialize animation variables
    xor a
    ld (anim_tile_timer), a
    ld (anim_tile_frame), a

    ; Set default global animation speed
    ld a, 1
    ld (anim_tile_speed), a

    ; Upload initial animation frame state immediately
    call call_update_animated_tiles_vram_resident

    ret

; ==================================================================
; ANIMATED TILES UPDATE FUNCTIONS
; ==================================================================

; ------------------------------------------------------------------
; update_animated_tiles
; Update animation frame and redraw animated tiles if needed
; Call this every frame from main loop
; ------------------------------------------------------------------
update_animated_tiles:
    ; Skip animation work on screens with no animated tile groups
    ld a, (current_screen_anim_group_count)
    or a
    ret z

    ; Increment timer
    ld a, (anim_tile_timer)
    inc a
    ld (anim_tile_timer), a

    ; Check if it's time to advance frame
    ld b, a
    ld a, (anim_tile_speed)
    or a
    jr nz, .anim_speed_ok
    ld a, 1
    ld (anim_tile_speed), a
.anim_speed_ok:
    cp b
    ret nc                          ; Not yet time to update (timer < speed)

    ; Reset timer
    xor a
    ld (anim_tile_timer), a

    ; Advance global animation counter
    ld a, (anim_tile_frame)
    inc a
    ld (anim_tile_frame), a

    ; Update all animated tiles in VRAM
    call call_update_animated_tiles_vram_resident

    ret

; ------------------------------------------------------------------
; update_animated_tiles_vram
; Update pattern data in VRAM for all animated tiles
; This updates the actual tile patterns based on current frame
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
update_animated_tiles_vram:
    ; Protect VDP port sequence from ISR VRAM writes.
    ; Re-enables on exit unless a far trampoline still owns the mapper window.
    di
    ld hl, anim_tile_table

.anim_vram_loop:
    ld a, (hl)                      ; A = target char code
    cp 255
    jp z, .anim_vram_done

    push af                         ; Save target char code
    inc hl
    ld a, (hl)                      ; A = chars per tile
    push af
    inc hl
    ld b, (hl)                      ; B = frame count
    inc hl
    inc hl                          ; Skip speed byte (reserved)
    ld c, (hl)                      ; C = bytes per frame
    inc hl
    ld e, (hl)                      ; DE = data pointer
    inc hl
    ld d, (hl)
    inc hl                          ; HL = next table entry
    push hl
    ex de, hl                       ; HL = data pointer

    ; frame = global_frame % frame_count
    ; Fast path for power-of-two frame counts: frame & (count-1)
    ld a, b
    dec a
    ld d, a
    and b
    jr nz, .anim_mod_slow
    ld a, (anim_tile_frame)
    and d
    jr .anim_mod_done
.anim_mod_slow:
    ld a, (anim_tile_frame)
.anim_mod_loop:
    cp b
    jr c, .anim_mod_done
    sub b
    jr .anim_mod_loop
.anim_mod_done:

    ; DE = frame offset (frame * bytes_per_frame)
    ld b, a
    ld d, 0
    ld e, 0
.anim_mul_loop:
    ld a, b
    or a
    jr z, .anim_mul_done
    ld a, e
    add a, c
    ld e, a
    ld a, d
    adc a, 0
    ld d, a
    dec b
    jr .anim_mul_loop
.anim_mul_done:
    add hl, de                      ; HL = frame data pointer

    pop de                          ; DE = next table entry pointer
    pop af
    ld b, a                         ; B = chars per tile
    pop af
    ld c, a                         ; C = target char code
    push de

.anim_char_loop:
    ld a, b
    or a
    jr z, .anim_char_done

    push bc
    push hl
    ld a, c
    call anim_upload_char_frame
    pop hl
    pop bc

    ld de, 16
    add hl, de                      ; Next char frame chunk
    inc c                           ; Next target char code
    dec b
    jr .anim_char_loop

.anim_char_done:
    pop de
    ex de, hl                       ; HL = next table entry
    jp .anim_vram_loop

.anim_vram_done:

    ld a, (interrupt_in_progress)
    or a
    jp nz, .animtiles_vram_irq_done
    ld a, (far_call_irq_lock_depth)
    or a
    jp nz, .animtiles_vram_irq_done
    ei
.animtiles_vram_irq_done:
    ret

; ------------------------------------------------------------------
; set_animation_speed
; Set global animation speed for all animated tiles
; Input:  A = Speed (frames between updates)
; ------------------------------------------------------------------
set_animation_speed:
    or a
    jr nz, .anim_speed_store
    ld a, 1
.anim_speed_store:
    ld (anim_tile_speed), a
    ret

; ------------------------------------------------------------------
; anim_copy_8_bytes
; Copy 8 bytes from CPU memory to VRAM
; Input: DE = source pointer, HL = VRAM destination
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
anim_copy_8_bytes:
    push de                         ; Save source pointer
    push hl                         ; Save VRAM destination
    pop de                          ; DE = VRAM destination for FAST_LDIRVM
    pop hl                          ; HL = source pointer for FAST_LDIRVM
    ld bc, 8
    call FAST_LDIRVM
    push hl
    pop de                          ; Preserve legacy postcondition: DE = source + 8
    ret

; ==================================================================
; anim_upload_char_frame
; Upload one animated char (pattern + color) to all 3 Screen 2 banks
; Input: A = target char code, HL = source frame chunk (16 bytes)
; Source layout: 8 pattern bytes + 8 color bytes
; Destroys: AF, BC, DE, HL
; ==================================================================
anim_upload_char_frame:
    push af
    push bc
    push de
    push hl

    ; BC = target char offset (charCode * 8)
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    ld b, h
    ld c, l

    pop hl
    ex de, hl                      ; DE = source pattern pointer

    ; Pattern bank 0
    push de
    ld hl, CHRTBL2
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Pattern bank 1
    push de
    ld hl, CHRTBL2 + #800
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Pattern bank 2
    ld hl, CHRTBL2 + #1000
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc

    ; DE now points to color bytes (source + 8)
    ; Color bank 0
    push de
    ld hl, CLRTBL2
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Color bank 1
    push de
    ld hl, CLRTBL2 + #800
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Color bank 2
    ld hl, CLRTBL2 + #1000
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc

    pop de
    pop bc
    pop af
    ret

; ==================================================================
; TRANSFORM MODE COMPATIBILITY STUBS
; ==================================================================
; Transform-mode tiles are precomputed into normal frame data by the
; generator. Runtime VRAM read/modify/write is intentionally disabled.

update_animated_transform_tiles_vram:
    ret

anim_transform_char_frame:
    ret

anim_transform_vram_block:
    ret

; ==================================================================
; ANIMATED TILE DEFINITIONS (AUTO-GENERATED)
; ==================================================================

; ------------------------------------------------------------------
; Animated tile mapping table
; Format:
;   db targetCharCode, charsPerTile, numFrames, speed, bytesPerFrame
;   dw frameDataPointer
; ------------------------------------------------------------------
anim_tile_table:
    db 134, 1, 2, 1, 16    ; gema -> tile tile_1772126067456
    dw anim_group_0_gema
    db 141, 1, 2, 1, 16    ; gem_extra_jump -> tile tile_1772380335352
    dw anim_group_1_gem_extra_jump
    db 168, 1, 2, 1, 16    ; New Boss_part_4_4 -> tile tile_boss_1777550194409
    dw anim_group_2_new_boss_part_4_4
    db 255                          ; End marker

; ------------------------------------------------------------------
; Transform tile mapping table
; Format:
;   db targetCharCode, charsPerTile, opCode, flags
; flags:
;   bit0 = apply vertical transform on color rows
; ------------------------------------------------------------------
anim_transform_table:
    ; Transform groups are precomputed as frame data in anim_tile_table
    db 255                          ; End marker

; ==================================================================
; ANIMATION FRAME DATA
; ==================================================================
anim_group_0_gema:
    ; Group "gema" targetChar=134 chars=1
    ; Frame 0: gema
    db #80, #18, #3C, #7E, #7E, #34, #18, #01, #A1, #A1, #A1, #A1, #A1, #A1, #A1, #A1
    ; Frame 1: gema_f0
    db #01, #18, #3C, #7E, #7E, #34, #18, #80, #A1, #A1, #A1, #A1, #A1, #A1, #A1, #A1

anim_group_1_gem_extra_jump:
    ; Group "gem_extra_jump" targetChar=141 chars=1
    ; Frame 0: gem_extra_jump
    db #00, #00, #38, #38, #38, #00, #00, #00, #F1, #F1, #71, #E1, #E1, #F1, #F1, #F1
    ; Frame 1: gem_extra_jump_f0
    db #00, #10, #38, #7C, #38, #10, #00, #00, #F1, #F1, #F1, #71, #E1, #F1, #F1, #F1

anim_group_2_new_boss_part_4_4:
    ; Group "New Boss_part_4_4" targetChar=168 chars=1
    ; Frame 0: New Boss_part_4_4
    db #7E, #FF, #FF, #FF, #FF, #FF, #FF, #7E, #E1, #E1, #E1, #E1, #F1, #F1, #F1, #F1
    ; Frame 1: New Boss_part_4_4
    db #FF, #BF, #FC, #F8, #F8, #FC, #BF, #FE, #E1, #E1, #E1, #E1, #E1, #E1, #E1, #E1


; ------------------------------------------------------------------
; register_animated_tile
; Runtime registration is not supported in this generator version.
; Input:  A = Tile ID to animate
;         B = Number of frames (2-4)
;         C = Animation speed
; Output: A = 0 if failed (table full), 1 if success
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
register_animated_tile:
    xor a                           ; Not supported (static generated table)
    ret

; ------------------------------------------------------------------
; get_tile_animation_frame
; Get current animation frame for a tile
; Input:  A = target char code
; Output: A = Current frame index (mod numFrames), or 0 if not animated
; Destroys: BC, DE, HL
; ------------------------------------------------------------------
get_tile_animation_frame:
    ld c, a                         ; C = char code to search
    ld hl, anim_tile_table

.anim_search_loop:
    ld a, (hl)
    cp 255
    jr z, .anim_not_found
    cp c
    jr z, .anim_found_tile

    ld de, ANIM_TILE_ENTRY_SIZE
    add hl, de
    jr .anim_search_loop

.anim_found_tile:
    inc hl
    inc hl
    ld b, (hl)                      ; B = numFrames
    ld a, (anim_tile_frame)
.anim_found_mod:
    cp b
    jr c, .anim_found_done
    sub b
    jr .anim_found_mod
.anim_found_done:
    ret

.anim_not_found:
    xor a
    ret

; ==================================================================
; END OF ANIMATED TILES SYSTEM
; ==================================================================
; @mideas:endblock id=runtime.animtiles.core


; --- End of Far Bank 14 — pad to 8KB boundary ---
BANK_14_USED_END:
    ds #8000 - $, #FF
    org FAR_BANK_14_ROM_START + #2000

; ##################################################################
; FAR BANK 15 — [#6000h-#8000h] FAR CODE: boss_attacks
; Accessed ONLY via trampolines in bank 0 (entrypoint_far labels).
; At runtime: bank0 saves P1, maps bank15 to P1,
; calls routine, then restores P1.
; NOTE: routines in this bank MUST only call code in bank 0 or
;       primary banks (1-2). No far-to-far calls allowed.
; ##################################################################
FAR_BANK_15_ROM_START:

    org #6000

; ==================================================================
; BOSS ATTACK RUNTIME
; Split from bosses.asm so the boss core and projectile/attack code can
; occupy separate 8KB MegaROM code banks.
; ==================================================================
; @mideas:block id=runtime.boss.attacks kind=routine owner=bosses roots=draw_boss_attack,update_boss_projectile_runtime
; Register Contract:
; input: A = sprite asset index (#FF = placeholder)
; output: A = hardware sprite base pattern number
; clobbers: AF, BC, HL
boss_attack_get_sprite_pattern:
    cp #FF
    jp z, .bagsp_placeholder
    ld c, a
    ld b, 0
    ld hl, sprite_asset_base_pattern_slot_runtime
    add hl, bc
    ld a, (hl)
    add a, a
    add a, a
    ret
.bagsp_placeholder:
    ld a, (sprite_placeholder_base_pattern_num)
    ret

; Register Contract:
; input: HL = boss attack record
;        B  = base X
;        C  = base Y
;        D  = hardware sprite slot to use
;        E  = sprite color
; output: dispatches to the matching attack renderer
; clobbers: AF plus the selected renderer's documented clobbers

draw_boss_attack:
    jp draw_boss_projectile_attack

draw_boss_projectile_attack:
    push ix
    push hl
    pop ix
    ld a, (boss_projectile_active)
    or a
    jr nz, .dbpa_done

    ld a, b
    add a, (ix+5)
    ld (boss_projectile_x), a
    ld a, c
    add a, (ix+6)
    ld (boss_projectile_y), a
    ld a, d
    ld (boss_projectile_sprite_slot), a
    ld a, (ix+13)
    ld (boss_projectile_layer_count), a
    ld a, (ix+14)
    ld (boss_projectile_frame_count), a
    ld a, (ix+15)
    ld (boss_projectile_color), a
    ld a, (ix+17)
    ld (boss_projectile_color2), a
    ld a, (ix+1)
    call boss_attack_get_sprite_pattern
    ld (boss_projectile_pattern), a

    ld a, (ix+3)
    or a
    jr nz, .dbpa_speed_ok
    ld a, 3
.dbpa_speed_ok:
    ld (boss_projectile_speed), a

    ld a, (ix+7)
    or a
    jr nz, .dbpa_range_ok
    ld a, 160
.dbpa_range_ok:
    ld (boss_projectile_range), a

    call call_sync_player_runtime_from_entity_resident
    call boss_projectile_select_velocity
    xor a
    ld (boss_projectile_distance), a
    ld a, 1
    ld (boss_projectile_active), a
    call boss_projectile_show_current

.dbpa_done:
    pop ix
    ret

; Register Contract:
; input: IX = attack record, boss_projectile_x/y initialized
; output: boss_projectile_vel_x/y populated; player target actions aim with a 2D vector toward player
; clobbers: AF, BC, DE
boss_projectile_select_velocity:
    xor a
    ld (boss_projectile_vel_x), a
    ld (boss_projectile_vel_y), a
    ld a, (boss_behavior_target_type)
    cp BOSS_BEHAVIOR_TARGET_PLAYER_CURRENT
    jr c, .bpsd_fixed
    cp BOSS_BEHAVIOR_TARGET_BOSS_RELATIVE
    jr c, .bpsd_player

.bpsd_fixed:
    ld a, (boss_projectile_speed)
    ld b, a
    ld a, (ix+4)
    cp BOSS_DIR_RIGHT
    jr z, .bpsd_fixed_right
    cp BOSS_DIR_UP
    jr z, .bpsd_store_neg_y
    cp BOSS_DIR_DOWN
    jr z, .bpsd_fixed_down
    jr .bpsd_store_neg_x
.bpsd_fixed_right:
    ld a, b
    ld (boss_projectile_vel_x), a
    ret
.bpsd_fixed_down:
    ld a, b
    ld (boss_projectile_vel_y), a
    ret
.bpsd_store_neg_x:
    xor a
    sub b
    ld (boss_projectile_vel_x), a
    ret
.bpsd_store_neg_y:
    xor a
    sub b
    ld (boss_projectile_vel_y), a
    ret

.bpsd_apply_sign:
    ld c, a
    ld a, b
    or a
    ld a, c
    ret z
    xor a
    sub c
    ret

.bpsd_scale_component:
    ld a, d
    or a
    ret z
    ld a, c
    or a
    ret z
    xor a
    ld e, d
.bpsd_mul_loop:
    add a, c
    jr nc, .bpsd_mul_ok
    ld a, #FF
    jr .bpsd_divide
.bpsd_mul_ok:
    dec e
    jr nz, .bpsd_mul_loop
    ld e, a
    ld a, b
    srl a
    add a, e
    jr nc, .bpsd_divide
    ld a, #FF
.bpsd_divide:
    ld e, 0
.bpsd_div_loop:
    cp b
    jr c, .bpsd_div_done
    sub b
    inc e
    jr .bpsd_div_loop
.bpsd_div_done:
    ld a, e
    ret

.bpsd_player:
    ld a, (player_x)
    add a, 8
    ld b, a
    ld a, (boss_projectile_x)
    ld c, a
    ld a, b
    cp c
    jr z, .bpsd_x_zero
    jr c, .bpsd_x_neg
    sub c
    ld (boss_projectile_abs_x), a
    xor a
    ld (boss_projectile_sign_x), a
    jr .bpsd_read_y
.bpsd_x_neg:
    ld a, c
    sub b
    ld (boss_projectile_abs_x), a
    ld a, 1
    ld (boss_projectile_sign_x), a
    jr .bpsd_read_y
.bpsd_x_zero:
    xor a
    ld (boss_projectile_abs_x), a
    ld (boss_projectile_sign_x), a
.bpsd_read_y:
    ld a, (player_y)
    add a, 8
    ld b, a
    ld a, (boss_projectile_y)
    ld c, a
    ld a, b
    cp c
    jr z, .bpsd_y_zero
    jr c, .bpsd_y_neg
    sub c
    ld (boss_projectile_abs_y), a
    xor a
    ld (boss_projectile_sign_y), a
    jr .bpsd_choose_major
.bpsd_y_neg:
    ld a, c
    sub b
    ld (boss_projectile_abs_y), a
    ld a, 1
    ld (boss_projectile_sign_y), a
    jr .bpsd_choose_major
.bpsd_y_zero:
    xor a
    ld (boss_projectile_abs_y), a
    ld (boss_projectile_sign_y), a
.bpsd_choose_major:
    ld a, (boss_projectile_abs_x)
    ld b, a
    ld a, (boss_projectile_abs_y)
    ld c, a
    ld a, b
    or c
    ret z
    ld a, b
    cp c
    jr c, .bpsd_y_major

.bpsd_x_major:
    ld a, (boss_projectile_speed)
    ld d, a
    ld a, (boss_projectile_sign_x)
    ld b, a
    ld a, d
    call .bpsd_apply_sign
    ld (boss_projectile_vel_x), a
    ld a, (boss_projectile_abs_x)
    ld b, a
    ld a, (boss_projectile_abs_y)
    ld c, a
    call .bpsd_scale_component
    ld c, a
    ld a, (boss_projectile_sign_y)
    ld b, a
    ld a, c
    call .bpsd_apply_sign
    ld (boss_projectile_vel_y), a
    ret

.bpsd_y_major:
    ld a, (boss_projectile_speed)
    ld d, a
    ld a, (boss_projectile_sign_y)
    ld b, a
    ld a, d
    call .bpsd_apply_sign
    ld (boss_projectile_vel_y), a
    ld a, (boss_projectile_abs_y)
    ld b, a
    ld a, (boss_projectile_abs_x)
    ld c, a
    call .bpsd_scale_component
    ld c, a
    ld a, (boss_projectile_sign_x)
    ld b, a
    ld a, c
    call .bpsd_apply_sign
    ld (boss_projectile_vel_x), a
    ret

; Register Contract:
; input: boss_projectile_* RAM state
; output: active simple boss projectile moved one step or hidden when finished
; clobbers: AF, BC, DE, HL
update_boss_projectile_runtime:
    ld a, (boss_projectile_active)
    or a
    ret z
    ld a, (boss_projectile_distance)
    ld b, a
    ld a, (boss_projectile_speed)
    add a, b
    ld (boss_projectile_distance), a
    ld b, a
    ld a, (boss_projectile_range)
    cp b
    jr c, .ubpr_hide
    jr z, .ubpr_hide

    ld a, (boss_projectile_x)
    ld b, a
    ld a, (boss_projectile_vel_x)
    add a, b
    ld (boss_projectile_x), a
    ld a, (boss_projectile_y)
    ld b, a
    ld a, (boss_projectile_vel_y)
    add a, b
    ld (boss_projectile_y), a
.ubpr_bounds:
    ld a, (boss_projectile_x)
    cp 248
    jr nc, .ubpr_hide
    ld a, (boss_projectile_y)
    cp 208
    jr nc, .ubpr_hide
    call boss_projectile_show_current
    ret
.ubpr_hide:
    call boss_projectile_hide_all
    xor a
    ld (boss_projectile_active), a
    ret

; Register Contract:
; input: boss_projectile_sprite_slot/layer_count
; output: all hardware sprite layers used by the projectile are hidden
; clobbers: AF, BC, DE, HL
boss_projectile_hide_all:
    ld a, (boss_projectile_sprite_slot)
    call call_hide_sprite_resident
    ld a, (boss_projectile_layer_count)
    cp 2
    ret c
    ld a, (boss_projectile_sprite_slot)
    inc a
    call call_hide_sprite_resident
    ret

; Register Contract:
; input: boss_projectile_* RAM state
; output: projectile sprite attributes written for the first two MSX1 layers
; clobbers: AF, BC, DE, HL
boss_projectile_show_current:
    ld a, (boss_projectile_pattern)
    ld d, a
    ld a, (boss_projectile_frame_count)
    cp 2
    jr c, .bpsc_pattern_ready
    ld a, (boss_runtime_tick)
    and #08
    jr z, .bpsc_pattern_ready
    ld a, (boss_projectile_layer_count)
    add a, a
    add a, a
    add a, d
    ld d, a
.bpsc_pattern_ready:
    ld a, (boss_projectile_x)
    ld b, a
    ld a, (boss_projectile_y)
    ld c, a
    ld a, (boss_projectile_color)
    ld e, a
    ld a, (boss_projectile_sprite_slot)
    call call_show_sprite_resident
    ld a, (boss_projectile_layer_count)
    cp 2
    ret c
    ld a, (boss_projectile_x)
    ld b, a
    ld a, (boss_projectile_y)
    ld c, a
    ld a, d
    add a, 4
    ld d, a
    ld a, (boss_projectile_color2)
    ld e, a
    ld a, (boss_projectile_sprite_slot)
    inc a
    call call_show_sprite_resident
    ret

